-- Migration 149: {VIDEO_DESC} pipeline node — a sanitized whole-clip description.
--
-- Minting_Workflow.md §2 + Cinematic Engine §4: the V2V "core" stylization needs a
-- description of what is actually IN the trimmed 1–15s clip so the cel-shaded restyle
-- tracks the real footage (not just the still-frame {SUBJECT_DESC}). That description
-- is a Vision-LLM read of the clip's sampled frames, generated by moment-clip-attach
-- ONLY AFTER pre-gen moderation has approved the upload (it is another CSAM checkpoint
-- — a description is never produced for content that failed moderation).
--
-- Two governance walls (Hard Rule 39):
--   * the text is SANITIZED and dropped into a VARIABLE prompt slot ({VIDEO_DESC})
--     where the constant STYLE-LOCK / CONSTRAINTS blocks always win;
--   * it feeds the V2V CORE node only — NEVER the two agnostic bridge plates (those
--     stay character-agnostic, which is the whole point of the agnostic-plate design).
--
-- Persisted twice for reproducibility: on moments (the source of truth for the clip)
-- and copied onto cinematic_generations at generation time (so a re-run reproduces the
-- exact prompt inputs that produced a given seed — Hard Rule 39 "seed/version" intent).

-- ── moments: the clip description (set post-moderation, attached clips only) ──────
ALTER TABLE public.moments
  ADD COLUMN IF NOT EXISTS clip_video_desc TEXT;

COMMENT ON COLUMN public.moments.clip_video_desc IS
  'Sanitized Vision-LLM description of the attached clip (moment-clip-attach, after '
  'moderation passes). Feeds the V2V core stylization slot {VIDEO_DESC} only — never '
  'the agnostic bridge plates (Hard Rule 39).';

-- ── cinematic_generations: the copy captured at generation time ──────────────────
ALTER TABLE public.cinematic_generations
  ADD COLUMN IF NOT EXISTS video_desc TEXT;

-- ── moment_set_clip_video_desc: the single write path (service-only) ─────────────
-- Kept separate from moment_attach_clip so attach stays atomic and the (optional,
-- best-effort) description call can't fail the moderation/attach transaction. Only an
-- ATTACHED clip may carry a description — a rejected/flagged upload never gets one.
CREATE OR REPLACE FUNCTION public.moment_set_clip_video_desc(
  p_moment_id UUID,
  p_owner     UUID,
  p_desc      TEXT
)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_status TEXT;
BEGIN
  SELECT clip_status INTO v_status
  FROM public.moments WHERE id = p_moment_id AND owner_user_id = p_owner;
  IF NOT FOUND THEN RAISE EXCEPTION 'Moment not found for owner: %', p_moment_id; END IF;
  IF v_status IS DISTINCT FROM 'attached' THEN
    RAISE EXCEPTION 'Clip is not attached (status: %) — no description allowed', v_status;
  END IF;

  UPDATE public.moments
  SET clip_video_desc = NULLIF(btrim(left(p_desc, 500)), '')
  WHERE id = p_moment_id;
END;
$$;

REVOKE ALL ON FUNCTION public.moment_set_clip_video_desc(UUID, UUID, TEXT)
  FROM PUBLIC, anon, authenticated;

-- ── apply-time smoke: description only allowed on an attached clip ────────────────
DO $$
DECLARE v_user UUID; v_moment UUID; v_err BOOLEAN := FALSE; v_desc TEXT;
BEGIN
  SELECT id INTO v_user FROM auth.users LIMIT 1;
  IF v_user IS NULL THEN
    RAISE NOTICE 'clip-video-desc smoke SKIPPED (no auth user)';
    RETURN;
  END IF;

  v_moment := public.moment_record(v_user, 'youtube', 'vdesc-smoke-' || gen_random_uuid()::TEXT,
                                   'https://example.com/post', NULL, 1000, TRUE, '@smoke');
  PERFORM public.moment_pre_gen_moderate(v_moment, 'approved', NULL, FALSE, 'sim');

  -- Before attach: setting a description must raise.
  BEGIN
    PERFORM public.moment_set_clip_video_desc(v_moment, v_user, 'a person waving');
  EXCEPTION WHEN OTHERS THEN v_err := TRUE;
  END;
  IF NOT v_err THEN RAISE EXCEPTION 'SMOKE FAIL: desc must require an attached clip'; END IF;

  -- Attach, then description sticks (and is trimmed/sanitized of surrounding space).
  PERFORM public.moment_attach_clip(v_moment, v_user,
    v_user::text || '/' || v_moment::text || '/clip.mp4', ARRAY[]::TEXT[], 0, 5000, TRUE, 'attached');
  PERFORM public.moment_set_clip_video_desc(v_moment, v_user, '  a skateboarder landing a kickflip  ');
  SELECT clip_video_desc INTO v_desc FROM public.moments WHERE id = v_moment;
  IF v_desc <> 'a skateboarder landing a kickflip' THEN
    RAISE EXCEPTION 'SMOKE FAIL: clip_video_desc not stored/trimmed (got: %)', v_desc;
  END IF;

  DELETE FROM public.moments WHERE id = v_moment;
  RAISE NOTICE 'clip-video-desc smoke OK: attach-gated + trimmed';
END $$;
